#[path="../../research/sources/backend/tip_compile_module.rs"] mod original;
#[path="../src/assignment.rs"] mod port;
fn main(){let template=original::Vm::new().unwrap();let mut count=0;for typ in 0u16..30 {for bit in [false,true]{for mode in [1u16,5,6]{let mut v=template.clone();v.memory.map(0x70000000,vec![0;0x10000]).unwrap();let sp=0x70008000;let lhs=0x70001000;let this=0x70002000;v.set_register("ESP",sp as u128).unwrap();v.set_register("EBP",lhs as u128).unwrap();v.set_register("ESI",this as u128).unwrap();v.set_register("EAX",u128::from(bit)).unwrap();v.memory.write_u32(lhs,u32::from(typ)<<16|0x61).unwrap();v.memory.write_u32(lhs+0x14,0x70003000).unwrap();v.memory.write_u32(this,0x70004000).unwrap();v.memory.write_u32(sp+0x50,u32::from(mode)).unwrap();v.pc=0x0fabfe4b;let mut h=original::NoHost;for _ in 0..100 {if v.pc==0x0faab81f {assert_eq!(v.stack_argument(0).unwrap(),0x70003000);v.return_stdcall(0x1234,4).unwrap();} else if v.pc==0x0fac0ad4 {let got=v.stack_argument(0).unwrap() as u16;let operand=v.stack_argument(1).unwrap() as u16;assert_eq!(got,port::kind_2d_opcode(typ,Some(bit),Some(mode)).unwrap(),"type={typ} bit={bit} mode={mode}");assert_eq!(operand,0x1234);count+=1;break;}else{v.step(&mut h).unwrap();}}
}}}assert_eq!(count,180);println!("{count} original snapshot selector comparisons passed; FAAB81F slot fixture 0x1234");}
